import type {
  MessageView,
  SenderKeyEnvelopeView,
} from '../../../shared/contracts/messaging.contract.ts';
import type { UserId } from '../../user/domain/user.value-objects.ts';
import type {
  ChainIndex,
  EncryptedPayload,
  IdempotencyKey,
  KeyEpoch,
  MessageId,
  RoomId,
  X25519PublicKey,
} from './messaging.value-objects.ts';

/** What a sender submits. The id and timestamp are always generated by PostgreSQL. */
export type NewMessage = {
  readonly chainIndex: ChainIndex;
  readonly idempotencyKey: IdempotencyKey;
  readonly keyEpoch: KeyEpoch;
  readonly payload: EncryptedPayload;
  readonly roomId: RoomId;
  readonly senderId: UserId;
};

export class Message {
  get roomId(): RoomId {
    return this.draft.roomId;
  }

  get senderId(): UserId {
    return this.draft.senderId;
  }

  constructor(
    readonly id: MessageId,
    readonly createdAt: Date,
    readonly draft: NewMessage,
  ) {}

  toView(): MessageView {
    return {
      ...this.draft.payload.toWire(),
      chainIndex: this.draft.chainIndex,
      createdAt: this.createdAt.toISOString(),
      id: this.id,
      idempotencyKey: this.draft.idempotencyKey,
      keyEpoch: this.draft.keyEpoch,
      roomId: this.draft.roomId,
      senderId: this.draft.senderId,
    };
  }
}

/** A sender's chain key for one epoch, wrapped for one recipient. */
export type SenderKeyEnvelope = {
  readonly ephemeralPublicKey: X25519PublicKey;
  readonly keyEpoch: KeyEpoch;
  readonly payload: EncryptedPayload;
  readonly recipientId: UserId;
  readonly roomId: RoomId;
  readonly senderId: UserId;
};

export function envelopeView(envelope: SenderKeyEnvelope): SenderKeyEnvelopeView {
  return {
    ...envelope.payload.toWire(),
    ephemeralPublicKey: envelope.ephemeralPublicKey.toBase64(),
    keyEpoch: envelope.keyEpoch,
    recipientId: envelope.recipientId,
    roomId: envelope.roomId,
    senderId: envelope.senderId,
  };
}
